// FleetPanel — dashboard surface for the fleet app's tenant control
// plane. Two-pane layout: tenant list on the left, detail + event
// timeline on the right.
//
// Wire protocol:
//   GET  /api/apps/fleet/tenants[/<id>]   — registry reads (cheap, no envelope)
//   POST /api/apps/fleet/mcp              — JSON-RPC for everything mutating
//                                           (create / start / stop / delete /
//                                           support_login)
//
// fleet doesn't publish app-events today, so this panel polls every
// 8s instead of subscribing. If/when fleet starts emitting events
// (e.g. tenant.spawned, tenant.status_changed) drop in the standard
// useAppEvents hook from tables/crm and remove the timer.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  createSelectionGate,
  decodeToolResult,
  requestedUpdateVersion,
} from "./fleet-state";
import type { ReactNode } from "react";

// Local theme-token StatusPill — mirrors CRM/storage's vocabulary so
// fleet visually sits with the rest of the panels. The dashboard's JIT
// only emits utilities it actually sees referenced in its own source +
// these panels' bundled output; raw `text-blue-700`/`text-amber-700`
// from the ui-kit's StatusPill fall outside that scan and render as
// no-ops, which is what made fleet look different.
type PillVariant = "success" | "info" | "warn" | "error" | "neutral";

const PILL_CLASSES: Record<PillVariant, string> = {
  success: "bg-green/15 text-green",
  info: "bg-accent/15 text-accent",
  warn: "bg-warn/15 text-warn",
  error: "bg-red/15 text-red",
  neutral: "bg-bg-input text-text-dim",
};

function StatusPill({
  variant = "neutral",
  children,
}: {
  variant?: PillVariant;
  children: ReactNode;
}) {
  return (
    <span
      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium whitespace-nowrap ${PILL_CLASSES[variant]}`}
    >
      {children}
    </span>
  );
}

// Local shape for a card surface — matches CRM/storage's two-pane
// rounded panel style. Drops ui-kit's Card (which carried `text-blue-700`
// / `text-amber-700` in its descendants and dropped fleet off-theme).
function Card({
  className,
  children,
}: {
  className?: string;
  children: ReactNode;
}) {
  return (
    <div
      className={`flex flex-col overflow-hidden rounded-md border border-border bg-bg-card ${className ?? ""}`}
    >
      {children}
    </div>
  );
}

function CardHeader({
  title,
  subtitle,
  status,
}: {
  title: ReactNode;
  subtitle?: ReactNode;
  status?: { label: string; variant?: PillVariant };
}) {
  return (
    <header className="flex items-center gap-3 px-4 py-3 border-b border-border">
      <div className="min-w-0 flex-1 flex flex-col">
        <div className="text-text text-sm font-semibold truncate leading-tight">
          {title}
        </div>
        {subtitle && (
          <div className="text-text-dim text-xs truncate mt-0.5 leading-tight">
            {subtitle}
          </div>
        )}
      </div>
      {status && (
        <StatusPill variant={status.variant}>{status.label}</StatusPill>
      )}
    </header>
  );
}

function Row({
  leading,
  title,
  subtitle,
  trailing,
  onClick,
  flush,
}: {
  leading?: ReactNode;
  title: ReactNode;
  subtitle?: ReactNode;
  trailing?: ReactNode;
  onClick?: () => void;
  flush?: boolean;
}) {
  const cls = `flex items-center gap-3 w-full text-left px-4 py-2.5 ${flush ? "" : "border-t border-border"} ${onClick ? "hover:bg-bg-input" : ""}`;
  const inner = (
    <>
      {leading !== undefined && (
        <span className="flex-shrink-0 flex items-center justify-center">
          {leading}
        </span>
      )}
      <div className="min-w-0 flex-1 flex flex-col">
        <div className="text-text text-sm font-medium truncate leading-tight">
          {title}
        </div>
        {subtitle !== undefined && (
          <div className="text-text-dim text-xs truncate mt-0.5 leading-tight">
            {subtitle}
          </div>
        )}
      </div>
      {trailing !== undefined && (
        <span className="flex-shrink-0 text-xs text-text-dim tabular-nums">
          {trailing}
        </span>
      )}
    </>
  );
  if (onClick) {
    return (
      <button type="button" className={cls} onClick={onClick}>
        {inner}
      </button>
    );
  }
  return <div className={cls}>{inner}</div>;
}

interface NativePanelProps {
  appName: string;
  installId: number;
  projectId: string;
  instanceId?: number;
}

type ToolCaller = <T>(
  tool: string,
  args: Record<string, unknown>,
) => Promise<T>;

interface ProjectTemplateSummary {
  id: string;
  kind: string;
  name: string;
  description?: string;
  source: string;
  revision?: number;
}

interface ProjectTemplateListResp {
  project_id: string;
  templates: ProjectTemplateSummary[];
}

interface TemplateApplyResult {
  status: "pending" | "applied" | "failed";
  source_template_id: string;
  target_project_id?: string;
  target_template_id?: string;
  imported?: boolean;
  apply_result?: { warnings?: string[] };
  error?: string;
}

type TenantStatus =
  | "starting"
  | "setup_pending"
  | "active"
  | "suspended"
  | "stopped"
  | "disconnected"
  | "failed"
  | "deleted";

interface Tenant {
  id: string;
  slug: string;
  kind: "local" | "remote";
  base_url: string;
  config_dir?: string;
  owner_email: string;
  current_version?: string;
  target_version?: string;
  status: TenantStatus;
  last_seen_at?: string;
  last_health?: unknown;
  created_at: string;
  updated_at: string;
  // v0.3 — domain link (populated by tenant_attach_domain orchestration)
  domain?: string;
  domain_record_id?: string;
  domain_attached_at?: string;
  // v0.3 — auto-respawn bookkeeping
  respawn_attempts?: number;
  last_respawn_at?: string;
  // v0.6+ — host placement. instance_id 0 = local parent host;
  // >0 = a row in the Instances app (tenant runs on that VPS).
  instance_id?: number;
  ingress_mode?: "parent" | "direct_pending" | "direct";
  ingress_error?: string;
}

interface InstanceOption {
  id: number;
  name: string;
  public_ipv4: string;
  status: string;
}

// Fleet's /api/_meta response. The panel calls this once per refresh
// so it knows whether optional DNS/domain helpers are bound, what
// apexes are picker-eligible, and the npm latest apteva version for
// the version-drift indicator.
interface MetaResp {
  domains_available: boolean;
  certs_available: boolean;
  routes_available: boolean;
  public_host: string;
  domains: Array<{ name: string }>;
  certs: Record<
    string,
    { status: string; expires_at?: string; error?: string }
  >;
  apteva_latest?: string;
  // v0.8 — Instances integration. host_provider_available gates the
  // "Run on" picker; instances is the ready remote-host list (parent /
  // local instance already excluded server-side).
  host_provider_available?: boolean;
  instances?: InstanceOption[];
}

interface FleetEvent {
  id: number;
  tenant_id: string;
  kind: string;
  actor?: string;
  payload?: unknown;
  created_at: string;
}

interface TenantHost {
  id: number;
  tenant_id: string;
  hostname: string;
  domain_grant_id?: number;
  status: "pending" | "active" | "error";
  last_error?: string;
  created_at: string;
  updated_at: string;
}

interface ListResp {
  tenants: Tenant[] | null;
  count: number;
}

// Auto-setup response shape from tenant_create when the orchestrator
// succeeds. status==="active" and the three reveal fields are
// populated. On orchestrator failure the response degrades to the
// setup_pending shape (no admin_password/api_key) and we surface the
// auto_setup_error to the operator instead.
interface CreateResp {
  tenant_id: string;
  slug: string;
  base_url: string;
  status: TenantStatus;
  admin_email?: string;
  admin_password?: string;
  api_key?: string;
  setup_url?: string;
  setup_token?: string;
  auto_setup_error?: string;
  template?: TemplateApplyResult;
}

interface CredentialsReveal {
  slug: string;
  base_url: string;
  admin_email: string;
  admin_password: string;
  api_key: string;
}

interface GetResp {
  operation?: { id: string; operation: string; phase: string };
  setup_complete?: boolean;
  tenant: Tenant;
  events: FleetEvent[] | null;
  hosts?: TenantHost[];
  retained_source?: {
    tenant_id: string;
    source_instance_id: number;
    source_config_dir: string;
    source_slug: string;
    created_at: string;
  };
  // Only populated while tenant.status === "setup_pending"; surfaced
  // by handlers.go's decorateView so the operator can recover the
  // info on refresh without re-running tenant_create.
  setup_token?: string;
  setup_url?: string;
}

const API = "/api/apps/fleet";
const REFRESH_MS = 8000;
const META_REFRESH_MS = 60_000;

// Status → pill variant. Same five-color semantic palette CRM/storage
// use, so a list of mixed statuses reads as a coherent group.
const STATUS_VARIANT: Record<TenantStatus, PillVariant> = {
  starting: "info",
  setup_pending: "warn",
  active: "success",
  suspended: "warn",
  stopped: "neutral",
  disconnected: "warn",
  failed: "error",
  deleted: "neutral",
};

export default function FleetPanel({ projectId, installId }: NativePanelProps) {
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<GetResp | null>(null);
  const selectionGate = useRef(createSelectionGate());
  selectionGate.current.select(selectedId);
  const detailRequest = useRef<{
    id: string;
    controller: AbortController;
  } | null>(null);

  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<string>("");
  const [showCreate, setShowCreate] = useState(false);
  const [showStorage, setShowStorage] = useState(false);
  const [showConnect, setShowConnect] = useState(false);
  // Credentials returned by a successful auto-setup. Held in panel
  // state because tenant_create is the only chance to see the admin
  // password and api_key — fleet doesn't store the plaintext anywhere
  // after this. Cleared when the operator clicks "I've saved them".
  const [credentialsReveal, setCredentialsReveal] =
    useState<CredentialsReveal | null>(null);
  // /api/_meta snapshot. Populated on mount + every refresh tick. The
  // panel uses it to decide whether to render attach/update controls,
  // and to seed picker lists. Null until first fetch — the detail pane
  // hides those controls in that brief window rather than disabling
  // them, which is less jumpy.
  const [meta, setMeta] = useState<MetaResp | null>(null);
  const [showAttachDomain, setShowAttachDomain] = useState<Tenant | null>(null);
  const [showAttachHost, setShowAttachHost] = useState<Tenant | null>(null);
  const [showUpdate, setShowUpdate] = useState<Tenant | null>(null);
  const [showMigrate, setShowMigrate] = useState<Tenant | null>(null);
  const [showClone, setShowClone] = useState<Tenant | null>(null);
  const [showApplyTemplate, setShowApplyTemplate] = useState<Tenant | null>(
    null,
  );
  // Held in panel state because both fleet endpoints return sensitive
  // material the operator gets to see once and copy — same pattern as
  // the post-create credentialsReveal.
  const [revealedAPIKey, setRevealedAPIKey] = useState<{
    slug: string;
    base_url: string;
    api_key: string;
  } | null>(null);
  const [resetPassword, setResetPassword] = useState<{
    slug: string;
    base_url: string;
    admin_email: string;
    admin_password: string;
  } | null>(null);

  // Two query params travel on every call. The platform proxy uses
  // these to scope per-install state — same convention as tables/crm.
  const withParams = useCallback(
    (extra: Record<string, string> = {}) =>
      new URLSearchParams({
        project_id: projectId,
        install_id: String(installId),
        ...extra,
      }).toString(),
    [projectId, installId],
  );

  const httpGet = useCallback(
    async <T,>(path: string, signal?: AbortSignal): Promise<T> => {
      const res = await fetch(
        `${API}${path}${path.includes("?") ? "&" : "?"}${withParams()}`,
        {
          credentials: "same-origin",
          signal,
        },
      );
      if (!res.ok) {
        throw new Error(`${res.status}: ${await res.text().catch(() => "")}`);
      }
      return res.json();
    },
    [withParams],
  );

  // callTool — POST /api/apps/fleet/mcp with the JSON-RPC envelope
  // and unwrap result.content[0].text. Same shape every panel uses;
  // see apps/mcp/ads/ui/AdsPanel.tsx for the canonical version.
  const callTool = useCallback(
    async <T,>(tool: string, args: Record<string, unknown>): Promise<T> => {
      if (tool === "fleet_storage_list" || tool === "fleet_storage_cleanup") {
        const res = await fetch(`${API}/maintenance?${withParams()}`, {
          method: tool === "fleet_storage_list" ? "GET" : "POST",
          credentials: "same-origin",
          headers: { "content-type": "application/json" },
          ...(tool === "fleet_storage_cleanup"
            ? { body: JSON.stringify(args) }
            : {}),
        });
        if (!res.ok) throw new Error(await res.text());
        return res.json();
      }
      if (tool === "fleet_resume_setup" || tool === "fleet_recover_operation") {
        const action =
          tool === "fleet_resume_setup" ? "resume-setup" : "recover-operation";
        const res = await fetch(
          `${API}/tenants/${encodeURIComponent(String(args.tenant_id))}/${action}?${withParams()}`,
          {
            method: "POST",
            credentials: "same-origin",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(args),
          },
        );
        if (!res.ok) throw new Error(await res.text());
        return res.json();
      }

      const res = await fetch(`${API}/mcp?${withParams()}`, {
        method: "POST",
        credentials: "same-origin",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "tools/call",
          params: { name: tool, arguments: args },
        }),
      });
      if (!res.ok) {
        throw new Error(
          `${tool}: ${res.status} ${await res.text().catch(() => "")}`,
        );
      }
      const j = await res.json();
      return decodeToolResult<T>(j);
    },
    [withParams],
  );

  const [page, setPage] = useState(0);
  const [search, setSearch] = useState("");
  const [hasMore, setHasMore] = useState(false);
  const listRequest = useRef<{
    key: string;
    controller: AbortController;
  } | null>(null);
  const refreshList = useCallback(
    async (opts: { quiet?: boolean } = {}) => {
      const key = `${page}:${search}`;
      if (listRequest.current?.key === key) return;
      listRequest.current?.controller.abort();
      const controller = new AbortController();
      listRequest.current = { key, controller };
      if (!opts.quiet) setLoading(true);
      try {
        const r = await httpGet<ListResp & { has_more: boolean }>(
          `/tenants?limit=50&offset=${page * 50}&search=${encodeURIComponent(search)}`,
          controller.signal,
        );
        if (controller.signal.aborted) return;
        setTenants(r.tenants || []);
        setHasMore(r.has_more);
        setStatus(`Page ${page + 1} · ${(r.tenants || []).length} tenants`);
      } catch (e) {
        if (!controller.signal.aborted)
          setStatus(`Error: ${(e as Error).message}`);
      } finally {
        if (listRequest.current?.controller === controller) {
          listRequest.current = null;
          setLoading(false);
        }
      }
    },
    [httpGet, page, search],
  );
  useEffect(
    () => () => listRequest.current?.controller.abort(),
    [page, search],
  );

  const refreshDetail = useCallback(
    async (id: string) => {
      if (detailRequest.current?.id === id) return;
      detailRequest.current?.controller.abort();
      const controller = new AbortController();
      detailRequest.current = { id, controller };
      const accepts = selectionGate.current.request(id);
      try {
        const result = await httpGet<GetResp>(
          `/tenants/${encodeURIComponent(id)}`,
          controller.signal,
        );
        if (accepts()) setDetail(result);
      } catch (error) {
        if (!controller.signal.aborted && accepts()) {
          setStatus(`Error: ${(error as Error).message}`);
          setDetail(null);
        }
      } finally {
        if (detailRequest.current?.controller === controller)
          detailRequest.current = null;
      }
    },
    [httpGet],
  );
  useEffect(() => () => detailRequest.current?.controller.abort(), []);

  const metaBusy = useRef(false);
  const refreshMeta = useCallback(async () => {
    if (metaBusy.current) return;
    metaBusy.current = true;
    try {
      const r = await httpGet<MetaResp>("/_meta");
      setMeta(r);
    } catch {
      // _meta is opportunistic — a transient failure shouldn't toast
      // an error in the list status bar. The UI degrades to "no
      // integrations visible" until the next tick succeeds.
    } finally {
      metaBusy.current = false;
    }
  }, [httpGet]);

  useEffect(() => {
    refreshList();
    refreshMeta();
  }, [refreshList, refreshMeta]);

  useEffect(() => {
    if (!selectedId) {
      setDetail(null);
      return;
    }
    setDetail(null);
    refreshDetail(selectedId);
  }, [selectedId, refreshDetail]);

  // Tenant state changes quickly; integration catalogs, npm latest,
  // domains, and cert inventory do not. Poll them independently so
  // the fast status refresh does not fan out across every dependency.
  useEffect(() => {
    const t = window.setInterval(() => {
      refreshList({ quiet: true });
      if (selectedId) refreshDetail(selectedId);
    }, REFRESH_MS);
    return () => window.clearInterval(t);
  }, [refreshList, refreshDetail, selectedId]);

  useEffect(() => {
    const t = window.setInterval(refreshMeta, META_REFRESH_MS);
    return () => window.clearInterval(t);
  }, [refreshMeta]);

  const visibleDetail = detail?.tenant.id === selectedId ? detail : null;
  const selected = useMemo(
    () =>
      tenants.find((t) => t.id === selectedId) ||
      (detail?.tenant.id === selectedId ? detail.tenant : null),
    [tenants, selectedId, detail],
  );

  return (
    <div className="grid grid-cols-[340px_1fr] gap-3 h-full p-3 bg-bg">
      <TenantList
        onStorage={() => setShowStorage(true)}
        tenants={tenants}
        page={page}
        hasMore={hasMore}
        search={search}
        onSearch={(value) => {
          setSearch(value);
          setPage(0);
          setTenants([]);
        }}
        onPage={(value) => {
          setPage(value);
          setTenants([]);
        }}
        selectedId={selectedId}
        loading={loading}
        status={status}
        latest={meta?.apteva_latest}
        onSelect={setSelectedId}
        onCreate={() => setShowCreate(true)}
        onConnect={() => setShowConnect(true)}
        onRefresh={() => {
          refreshList();
          refreshMeta();
        }}
      />
      <TenantDetail
        key={selectedId}
        operation={visibleDetail?.operation}
        setupComplete={visibleDetail?.setup_complete}
        tenant={selected}
        events={visibleDetail?.events ?? null}
        hosts={visibleDetail?.hosts ?? []}
        retainedSource={visibleDetail?.retained_source ?? null}
        setupToken={visibleDetail?.setup_token ?? null}
        setupURL={visibleDetail?.setup_url ?? null}
        meta={meta}
        callTool={callTool}
        onOpenAttachDomain={(t) => setShowAttachDomain(t)}
        onOpenAttachHost={(t) => setShowAttachHost(t)}
        onOpenUpdate={(t) => setShowUpdate(t)}
        onOpenMigrate={(t) => setShowMigrate(t)}
        onOpenClone={(t) => setShowClone(t)}
        onOpenApplyTemplate={(t) => setShowApplyTemplate(t)}
        onSetupRecovered={setCredentialsReveal}
        onRevealAPIKey={setRevealedAPIKey}
        onResetPassword={setResetPassword}
        onAfterAction={async (after) => {
          await refreshList({ quiet: true });
          await refreshMeta();
          if (after === "deselect") {
            setSelectedId(null);
          } else if (selectedId) {
            await refreshDetail(selectedId);
          }
        }}
      />
      {showStorage && (
        <StorageDialog
          callTool={callTool}
          onClose={() => setShowStorage(false)}
        />
      )}
      {showCreate && (
        <CreateTenantDialog
          meta={meta}
          callTool={callTool}
          onClose={() => setShowCreate(false)}
          onSubmit={async ({
            slug,
            owner_email,
            instance_id,
            port,
            template_id,
            project_description,
          }) => {
            try {
              const r = await callTool<CreateResp>("tenant_create", {
                slug,
                owner_email,
                ...(instance_id ? { instance_id } : {}),
                ...(port ? { port } : {}),
                ...(template_id ? { template_id } : {}),
                ...(project_description ? { project_description } : {}),
              });
              await refreshList({ quiet: true });
              if (r.tenant_id) setSelectedId(r.tenant_id);
              setShowCreate(false);
              if (r.template?.status === "failed") {
                setStatus(
                  `Tenant created; template failed: ${r.template.error || "unknown error"}`,
                );
              } else if (r.template?.status === "pending") {
                setStatus(
                  "Tenant created; template will apply after setup is completed",
                );
              } else if (r.template?.apply_result?.warnings?.length) {
                setStatus(
                  `Tenant created with template warnings: ${r.template.apply_result.warnings.join("; ")}`,
                );
              }
              // Auto-setup happy path returns admin_password + api_key.
              // Surface them in a one-shot modal — fleet stores the
              // api_key sealed and never the plaintext password, so
              // this is the operator's only chance to capture them.
              if (r.admin_password && r.api_key && r.admin_email) {
                setCredentialsReveal({
                  slug: r.slug,
                  base_url: r.base_url,
                  admin_email: r.admin_email,
                  admin_password: r.admin_password,
                  api_key: r.api_key,
                });
              }
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {credentialsReveal && (
        <CredentialsRevealDialog
          creds={credentialsReveal}
          onClose={() => setCredentialsReveal(null)}
        />
      )}
      {showConnect && (
        <ConnectTenantDialog
          onClose={() => setShowConnect(false)}
          onSubmit={async (args) => {
            try {
              const r = await callTool<{ tenant_id: string }>(
                "tenant_connect",
                args,
              );
              await refreshList({ quiet: true });
              if (r.tenant_id) setSelectedId(r.tenant_id);
              setShowConnect(false);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showAttachDomain && meta && (
        <AttachDomainDialog
          tenant={showAttachDomain}
          meta={meta}
          onClose={() => setShowAttachDomain(null)}
          onSubmit={async (args) => {
            try {
              await callTool("tenant_attach_domain", {
                tenant_id: showAttachDomain.id,
                ...args,
              });
              await refreshList({ quiet: true });
              await refreshMeta();
              if (selectedId) await refreshDetail(selectedId);
              setShowAttachDomain(null);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showAttachHost && (
        <AttachTenantHostDialog
          tenant={showAttachHost}
          onClose={() => setShowAttachHost(null)}
          onSubmit={async (hostname) => {
            try {
              await callTool("tenant_host_attach", {
                tenant_id: showAttachHost.id,
                hostname,
              });
              if (selectedId) await refreshDetail(selectedId);
              setShowAttachHost(null);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showUpdate && (
        <UpdateVersionDialog
          tenant={showUpdate}
          latest={meta?.apteva_latest}
          onClose={() => setShowUpdate(null)}
          onSubmit={async (version) => {
            try {
              await callTool("tenant_update", {
                tenant_id: showUpdate.id,
                ...(version ? { version } : {}),
              });
              await refreshList({ quiet: true });
              if (selectedId) await refreshDetail(selectedId);
              setShowUpdate(null);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showMigrate && meta && (
        <MoveTenantDialog
          tenant={showMigrate}
          meta={meta}
          onClose={() => setShowMigrate(null)}
          onSubmit={async ({ instance_id, port, retain_source }) => {
            try {
              await callTool("tenant_migrate", {
                tenant_id: showMigrate.id,
                instance_id,
                ...(port ? { port } : {}),
                retain_source,
              });
              await refreshList({ quiet: true });
              if (selectedId) await refreshDetail(selectedId);
              setShowMigrate(null);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showClone && (
        <CloneTenantDialog
          tenant={showClone}
          meta={meta}
          onClose={() => setShowClone(null)}
          onSubmit={async ({ slug, owner_email, instance_id, port, start }) => {
            try {
              const r = await callTool<{ tenant_id: string }>("tenant_clone", {
                source_tenant_id: showClone.id,
                slug,
                ...(owner_email ? { owner_email } : {}),
                instance_id,
                ...(port ? { port } : {}),
                start,
              });
              await refreshList({ quiet: true });
              if (r.tenant_id) setSelectedId(r.tenant_id);
              setShowClone(null);
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {showApplyTemplate && (
        <ApplyTemplateDialog
          tenant={showApplyTemplate}
          callTool={callTool}
          onClose={() => setShowApplyTemplate(null)}
          onSubmit={async ({
            template_id,
            project_description,
            target_project_id,
          }) => {
            try {
              const result = await callTool<TemplateApplyResult>(
                "tenant_apply_template",
                {
                  tenant_id: showApplyTemplate.id,
                  template_id,
                  ...(target_project_id ? { target_project_id } : {}),
                  ...(project_description ? { project_description } : {}),
                },
              );
              setShowApplyTemplate(null);
              await refreshDetail(showApplyTemplate.id);
              const warnings = result.apply_result?.warnings ?? [];
              setStatus(
                warnings.length
                  ? `Template applied with warnings: ${warnings.join("; ")}`
                  : "Template applied",
              );
              return { ok: true };
            } catch (e) {
              return { ok: false, error: (e as Error).message };
            }
          }}
        />
      )}
      {revealedAPIKey && (
        <RevealAPIKeyDialog
          data={revealedAPIKey}
          onClose={() => setRevealedAPIKey(null)}
        />
      )}
      {resetPassword && (
        <ResetPasswordDialog
          data={resetPassword}
          onClose={() => setResetPassword(null)}
        />
      )}
    </div>
  );
}

// ─── List pane ──────────────────────────────────────────────────────

function TenantList({
  page,
  hasMore,
  search,
  onSearch,
  onPage,
  onStorage,
  tenants,
  selectedId,
  loading,
  status,
  latest,
  onSelect,
  onCreate,
  onConnect,
  onRefresh,
}: {
  page: number;
  hasMore: boolean;
  search: string;
  onSearch: (v: string) => void;
  onPage: (v: number) => void;
  onStorage: () => void;
  tenants: Tenant[];
  selectedId: string | null;
  loading: boolean;
  status: string;
  latest?: string;
  onSelect: (id: string) => void;
  onCreate: () => void;
  onConnect: () => void;
  onRefresh: () => void;
}) {
  return (
    <Card className="h-full">
      <CardHeader
        title="Tenants"
        subtitle={loading ? "Loading…" : status}
        status={{ label: String(tenants.length), variant: "info" }}
      />
      <div className="flex items-center gap-2 px-4 py-2 border-b border-border">
        <button
          type="button"
          onClick={onCreate}
          className="px-2.5 py-1 rounded-md text-xs font-medium bg-accent/10 text-accent hover:bg-accent/15"
        >
          + Create local
        </button>
        <button
          type="button"
          onClick={onConnect}
          className="px-2.5 py-1 rounded-md text-xs font-medium bg-bg-input hover:bg-bg-hover text-text"
        >
          Connect remote
        </button>
        <span className="flex-1" />
        <button
          type="button"
          onClick={onRefresh}
          title="Refresh"
          className="px-2 py-1 rounded-md text-xs text-text-dim hover:text-text hover:bg-bg-input"
        >
          ↻
        </button>
      </div>
      <div className="px-4 py-2 flex gap-2">
        <input
          aria-label="Search tenants"
          placeholder="Search tenants…"
          value={search}
          onChange={(e) => onSearch(e.target.value)}
          className="w-full min-w-0 bg-bg-input rounded p-1 text-xs"
        />
        <button
          aria-label="Previous page"
          disabled={page === 0 || loading}
          onClick={() => onPage(page - 1)}
        >
          ←
        </button>
        <button
          aria-label="Next page"
          disabled={!hasMore || loading}
          onClick={() => onPage(page + 1)}
        >
          →
        </button>
      </div>
      <button
        onClick={onStorage}
        className="px-4 py-1 text-xs text-left text-text-dim"
      >
        Local storage and cleanup…
      </button>
      <div className="flex-1 overflow-y-auto">
        {tenants.length === 0 && !loading && (
          <p className="text-xs text-text-dim px-4 py-6 text-center">
            No tenants yet. Create a local tenant or connect an existing apteva.
          </p>
        )}
        {tenants.map((t, i) => (
          <Row
            key={t.id}
            flush={i === 0}
            onClick={() => onSelect(t.id)}
            leading={<KindGlyph kind={t.kind} />}
            title={
              <span
                className={
                  t.id === selectedId ? "text-accent font-semibold" : ""
                }
              >
                {t.slug}
              </span>
            }
            subtitle={
              <span className="font-mono text-[10px] flex items-center gap-1.5">
                <span className="truncate">
                  {t.domain ? t.domain : shortBaseURL(t.base_url)}
                </span>
                <span className="text-text-dim">·</span>
                <span
                  className={
                    t.current_version ? "text-text-dim" : "text-text-dim italic"
                  }
                >
                  {t.current_version ? `v${t.current_version}` : "v—"}
                </span>
                {latest &&
                  t.current_version &&
                  t.current_version !== latest && (
                    <span title={`npm latest: ${latest}`} className="text-warn">
                      ↑
                    </span>
                  )}
              </span>
            }
            trailing={
              <div className="flex items-center gap-1.5">
                {(t.respawn_attempts ?? 0) > 0 && (
                  <span
                    title={`${t.respawn_attempts} auto-respawn${t.respawn_attempts === 1 ? "" : "s"}`}
                    className="text-[10px] font-medium text-warn px-1.5 py-0.5 rounded bg-warn/10"
                  >
                    ↻{t.respawn_attempts}
                  </span>
                )}
                <StatusPill variant={STATUS_VARIANT[t.status]}>
                  {t.status}
                </StatusPill>
              </div>
            }
          />
        ))}
      </div>
    </Card>
  );
}

function KindGlyph({ kind }: { kind: Tenant["kind"] }) {
  // Inline SVG instead of an emoji per project convention (memory:
  // feedback_no_emojis_in_app_ui). Local = server stack icon, remote
  // = cloud-ish icon. Both use currentColor and inherit text-text-dim
  // so they sit visually with the row text.
  if (kind === "local") {
    return (
      <svg
        width="14"
        height="14"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="text-text-dim"
        aria-label="local tenant"
      >
        <rect x="2" y="3" width="12" height="4" rx="1" />
        <rect x="2" y="9" width="12" height="4" rx="1" />
        <circle cx="4.5" cy="5" r="0.5" fill="currentColor" />
        <circle cx="4.5" cy="11" r="0.5" fill="currentColor" />
      </svg>
    );
  }
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="text-text-dim"
      aria-label="remote tenant"
    >
      <path d="M4.5 11.5a3 3 0 1 1 .8-5.9 3.5 3.5 0 0 1 6.7 1.1 2.5 2.5 0 0 1-.5 4.8H4.5z" />
    </svg>
  );
}

// ─── Detail pane ────────────────────────────────────────────────────

function TenantDetail({
  setupComplete,
  operation,
  tenant,
  events,
  hosts,
  retainedSource,
  setupToken,
  setupURL,
  meta,
  callTool,
  onOpenAttachDomain,
  onOpenAttachHost,
  onOpenUpdate,
  onOpenMigrate,
  onOpenClone,
  onOpenApplyTemplate,
  onSetupRecovered,
  onRevealAPIKey,
  onResetPassword,
  onAfterAction,
}: {
  setupComplete?: boolean;
  operation?: GetResp["operation"];
  tenant: Tenant | null;
  events: FleetEvent[] | null;
  hosts: TenantHost[];
  retainedSource: GetResp["retained_source"] | null;
  setupToken: string | null;
  setupURL: string | null;
  meta: MetaResp | null;
  callTool: <T>(tool: string, args: Record<string, unknown>) => Promise<T>;
  onOpenAttachDomain: (t: Tenant) => void;
  onOpenAttachHost: (t: Tenant) => void;
  onOpenUpdate: (t: Tenant) => void;
  onOpenMigrate: (t: Tenant) => void;
  onOpenClone: (t: Tenant) => void;
  onOpenApplyTemplate: (t: Tenant) => void;
  onSetupRecovered: (r: CredentialsReveal) => void;
  onRevealAPIKey: (r: {
    slug: string;
    base_url: string;
    api_key: string;
  }) => void;
  onResetPassword: (r: {
    slug: string;
    base_url: string;
    admin_email: string;
    admin_password: string;
  }) => void;
  onAfterAction: (after?: "deselect") => Promise<void>;
}) {
  const [busy, setBusy] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [confirmFinalize, setConfirmFinalize] = useState(false);
  const [supportURL, setSupportURL] = useState<{
    url: string;
    expires_at?: string;
  } | null>(null);
  const [supportDialog, setSupportDialog] = useState(false);
  const [supportReason, setSupportReason] = useState("");
  const [resetDialog, setResetDialog] = useState(false);

  // Reset transient detail state whenever the tenant changes.
  useEffect(() => {
    setBusy(null);
    setErr(null);
    setConfirmDelete(false);
    setConfirmFinalize(false);
    setSupportURL(null);
    setSupportDialog(false);
    setSupportReason("");
    setResetDialog(false);
  }, [tenant?.id]);

  if (!tenant) {
    return (
      <Card className="h-full items-center justify-center text-text-dim text-sm">
        <p>Select a tenant to see details, events, and actions.</p>
      </Card>
    );
  }

  const run = async (
    label: string,
    tool: string,
    args: Record<string, unknown>,
    after?: "deselect",
  ) => {
    setBusy(label);
    setErr(null);
    try {
      const result = await callTool<{
        next_step?: string;
        next_steps?: string;
        note?: string;
        admin_password?: string;
        api_key?: string;
      }>(tool, args);
      if (result.admin_password && result.api_key) {
        onSetupRecovered({
          slug: tenant.slug,
          base_url: tenant.base_url,
          admin_email: tenant.owner_email,
          admin_password: result.admin_password,
          api_key: result.api_key,
        });
      }

      setNotice(
        result.next_step || result.next_steps || result.note || "Completed",
      );
      await onAfterAction(after);
    } catch (e) {
      setErr((e as Error).message);
    } finally {
      setBusy(null);
    }
  };

  const isLocal = tenant.kind === "local";
  const isRunning = tenant.status === "active" || tenant.status === "starting";
  const isSetupPending =
    setupComplete === false || tenant.status === "setup_pending";
  // Host placement: instance_id 0/undefined = parent host; >0 = a VPS.
  const onParentHost = (tenant.instance_id ?? 0) === 0;
  const hostInstance = meta?.instances?.find(
    (i) => i.id === tenant.instance_id,
  );
  const canMigrate = isLocal && !isSetupPending;
  const canClone = isLocal;

  return (
    <>
      <Card className="h-full">
        <CardHeader
          title={tenant.slug}
          subtitle={
            <span className="font-mono text-[11px]">
              {tenant.base_url}
              {" · "}
              {onParentHost
                ? "local"
                : hostInstance
                  ? `on ${hostInstance.name}`
                  : `on instance ${tenant.instance_id}`}
              {tenant.current_version ? ` · v${tenant.current_version}` : ""}
            </span>
          }
          status={{
            label: tenant.status,
            variant: STATUS_VARIANT[tenant.status],
          }}
        />

        {notice && (
          <p role="status" className="px-4 py-2 text-sm">
            {notice}
          </p>
        )}
        {operation && (
          <div className="px-4 py-2 text-sm border-b border-border">
            <p>
              {operation.operation}: {operation.phase}
            </p>
            <p className="text-xs text-text-dim">
              Operation {operation.id}. Progress survives closing this panel.
            </p>
            <ActionButton
              label="Recover interrupted operation"
              busy={!!busy}
              onClick={() => {
                if (
                  window.confirm(
                    "Stop all runtimes recorded by this operation and preserve their data? Recovery is rejected while an operation is still executing.",
                  )
                )
                  run("recovery", "fleet_recover_operation", {
                    tenant_id: tenant.id,
                    confirm: true,
                  });
              }}
            />
          </div>
        )}
        <fieldset disabled={!!busy || !!operation} className="contents">
          {isSetupPending && (
            <ActionButton
              label="Resume setup"
              busy={!!busy}
              onClick={() =>
                run("setup", "fleet_resume_setup", { tenant_id: tenant.id })
              }
            />
          )}
          {!isLocal && tenant.status === "suspended" && (
            <ActionButton
              label="Resume monitoring"
              busy={!!busy}
              onClick={() =>
                run("resume", "tenant_start", { tenant_id: tenant.id })
              }
            />
          )}
          {/* Action bar. When setup_pending we hide the normal lifecycle
          buttons — the operator still needs to complete admin
          registration before Start/Stop/Support make sense. */}
          <div
            inert={!!busy || !!operation}
            className="flex flex-wrap items-center gap-2 px-4 py-2 border-b border-border"
          >
            {!isSetupPending && isLocal && !isRunning && (
              <ActionButton
                label="Start"
                busy={busy === "start"}
                onClick={() =>
                  run("start", "tenant_start", { tenant_id: tenant.id })
                }
              />
            )}
            {!isSetupPending && isLocal && isRunning && (
              <ActionButton
                label="Stop"
                busy={busy === "stop"}
                onClick={() =>
                  run("stop", "tenant_stop", { tenant_id: tenant.id })
                }
              />
            )}
            {!isSetupPending && !isLocal && tenant.status !== "suspended" && (
              <ActionButton
                label="Suspend"
                busy={busy === "stop"}
                onClick={() =>
                  run("stop", "tenant_stop", { tenant_id: tenant.id })
                }
              />
            )}
            {!isSetupPending && (
              <ActionButton
                label={supportURL ? "Open support URL" : "Support login"}
                busy={busy === "support"}
                onClick={async () => {
                  if (supportURL) {
                    window.open(supportURL.url, "_blank", "noopener");
                    return;
                  }
                  setSupportDialog(true);
                }}
              />
            )}
            {!isSetupPending && (
              <ActionButton
                label="Apply template…"
                onClick={() => onOpenApplyTemplate(tenant)}
              />
            )}
            {canMigrate && (
              <ActionButton
                label="Move…"
                onClick={() => onOpenMigrate(tenant)}
              />
            )}
            {canClone && (
              <ActionButton
                label="Clone…"
                onClick={() => onOpenClone(tenant)}
              />
            )}
            <span className="flex-1" />
            {confirmDelete ? (
              <>
                <span className="text-xs text-error">
                  {isLocal
                    ? "Stop process and wipe data dir?"
                    : "Remove from registry?"}
                </span>
                <ActionButton
                  label="Confirm delete"
                  tone="danger"
                  busy={busy === "delete"}
                  onClick={() =>
                    run(
                      "delete",
                      "tenant_delete",
                      { tenant_id: tenant.id, confirm: true },
                      "deselect",
                    )
                  }
                />
                <ActionButton
                  label="Cancel"
                  onClick={() => setConfirmDelete(false)}
                />
              </>
            ) : (
              <ActionButton
                label="Delete"
                tone="danger"
                onClick={() => setConfirmDelete(true)}
              />
            )}
          </div>

          {err && (
            <div className="px-4 py-2 text-xs text-error border-b border-border bg-error/5">
              {err}
            </div>
          )}

          {supportURL && (
            <div className="px-4 py-2 text-xs border-b border-border bg-accent/5 flex items-center gap-2">
              <span className="text-text-dim">Support session active</span>
              <a
                href={supportURL.url}
                target="_blank"
                rel="noopener"
                className="font-mono truncate text-accent underline"
              >
                {supportURL.url}
              </a>
              {supportURL.expires_at && (
                <span className="text-text-dim ml-auto">
                  expires {formatTime(supportURL.expires_at)}
                </span>
              )}
            </div>
          )}

          {retainedSource && (
            <div className="px-4 py-2 text-xs border-b border-border bg-warn/5 flex flex-wrap items-center gap-2">
              <span className="text-text-dim">
                Stopped migration source retained
              </span>
              <span className="font-mono text-text">
                instance {retainedSource.source_instance_id} ·{" "}
                {retainedSource.source_config_dir}
              </span>
              <span className="flex-1" />
              {confirmFinalize ? (
                <>
                  <span className="text-error">
                    Permanently remove retained source?
                  </span>
                  <ActionButton
                    label="Confirm removal"
                    tone="danger"
                    busy={busy === "finalize"}
                    onClick={async () => {
                      await run("finalize", "tenant_migrate_finalize", {
                        tenant_id: tenant.id,
                        confirm: true,
                      });
                      setConfirmFinalize(false);
                    }}
                  />
                  <ActionButton
                    label="Cancel"
                    onClick={() => setConfirmFinalize(false)}
                  />
                </>
              ) : (
                <ActionButton
                  label="Finalize source"
                  onClick={() => setConfirmFinalize(true)}
                />
              )}
            </div>
          )}

          {isSetupPending && (
            <SetupPendingBanner
              tenantId={tenant.id}
              baseURL={tenant.base_url}
              setupToken={setupToken}
              setupURL={setupURL}
              busy={busy === "attach"}
              onAttach={async (apiKey) => {
                setBusy("attach");
                setErr(null);
                try {
                  await callTool("tenant_attach_key", {
                    tenant_id: tenant.id,
                    api_key: apiKey,
                  });
                  await onAfterAction();
                } catch (e) {
                  setErr((e as Error).message);
                  throw e;
                } finally {
                  setBusy(null);
                }
              }}
            />
          )}

          {!isSetupPending && (
            <DomainBlock
              tenant={tenant}
              meta={meta}
              busy={busy === "detach-domain"}
              onAttach={() => onOpenAttachDomain(tenant)}
              onDetach={() =>
                run("detach-domain", "tenant_detach_domain", {
                  tenant_id: tenant.id,
                })
              }
            />
          )}

          {!isSetupPending && !onParentHost && (
            <HostedIngressBlock
              tenant={tenant}
              instance={hostInstance}
              busy={busy}
              onPrepare={() =>
                run("ingress-prepare", "tenant_ingress_prepare_direct", {
                  tenant_id: tenant.id,
                })
              }
              onVerify={() =>
                run("ingress-verify", "tenant_ingress_verify", {
                  tenant_id: tenant.id,
                })
              }
              onFinalize={() =>
                run("ingress-finalize", "tenant_ingress_finalize", {
                  tenant_id: tenant.id,
                })
              }
              onRestore={() =>
                run("ingress-restore", "tenant_ingress_rollback", {
                  tenant_id: tenant.id,
                })
              }
              onDisable={() =>
                run("ingress-disable", "tenant_ingress_rollback", {
                  tenant_id: tenant.id,
                  confirm_disable: true,
                })
              }
            />
          )}

          {!isSetupPending && (
            <TenantHostsBlock
              hosts={hosts}
              busyHostname={
                busy?.startsWith("remove-host:")
                  ? busy.slice("remove-host:".length)
                  : null
              }
              onAttach={() => onOpenAttachHost(tenant)}
              onRemove={(hostname) =>
                run(`remove-host:${hostname}`, "tenant_host_remove", {
                  tenant_id: tenant.id,
                  hostname,
                })
              }
            />
          )}

          {!isSetupPending && isLocal && (
            <VersionBlock
              tenant={tenant}
              latest={meta?.apteva_latest}
              onUpdate={() => onOpenUpdate(tenant)}
            />
          )}

          {!isSetupPending && (
            <CredentialsBlock
              tenantId={tenant.id}
              busyReveal={busy === "reveal-api-key"}
              busyReset={busy === "reset-password"}
              onReveal={async () => {
                setBusy("reveal-api-key");
                setErr(null);
                try {
                  const r = await callTool<{
                    slug: string;
                    base_url: string;
                    api_key: string;
                  }>("tenant_reveal_api_key", { tenant_id: tenant.id });
                  onRevealAPIKey(r);
                } catch (e) {
                  setErr((e as Error).message);
                } finally {
                  setBusy(null);
                }
              }}
              onReset={async () => {
                setResetDialog(true);
              }}
            />
          )}

          <div className="grid grid-cols-2 gap-0 border-b border-border">
            <Field label="Owner">{tenant.owner_email}</Field>
            <Field label="Kind">{tenant.kind}</Field>
            <Field label="Status">
              <StatusPill variant={STATUS_VARIANT[tenant.status]}>
                {tenant.status}
              </StatusPill>
            </Field>
            <Field label="Base URL" mono>
              <a
                href={tenant.base_url}
                target="_blank"
                rel="noopener"
                className="text-accent hover:underline"
              >
                {tenant.base_url}
              </a>
            </Field>
            <Field label="Last seen">{formatTime(tenant.last_seen_at)}</Field>
            {tenant.config_dir && (
              <Field label="Data dir" mono>
                {tenant.config_dir}
              </Field>
            )}
            <Field label="Created">{formatTime(tenant.created_at)}</Field>
            {(tenant.respawn_attempts ?? 0) > 0 && (
              <Field label="Auto-respawns">
                <span className="text-warn font-medium">
                  {tenant.respawn_attempts}
                </span>
                {tenant.last_respawn_at && (
                  <span className="text-text-dim">
                    {" "}
                    · last {formatTime(tenant.last_respawn_at)}
                  </span>
                )}
              </Field>
            )}
          </div>

          <div className="flex-1 overflow-y-auto">
            <div className="px-4 pt-3 pb-1 text-[11px] uppercase tracking-wider text-text-dim font-medium">
              Recent events
            </div>
            {!events || events.length === 0 ? (
              <p className="text-xs text-text-dim px-4 py-3">No events yet.</p>
            ) : (
              <ul className="px-4 pb-4">
                {events.map((e) => (
                  <EventRow key={e.id} ev={e} />
                ))}
              </ul>
            )}
          </div>
        </fieldset>
      </Card>
      {supportDialog && (
        <DialogFrame
          title={`Support login for ${tenant.slug}`}
          onClose={() => setSupportDialog(false)}
        >
          <p className="text-xs text-text-dim">
            The reason is written to the tenant audit trail.
          </p>
          <Label text="Reason">
            <textarea
              value={supportReason}
              onChange={(e) => setSupportReason(e.target.value)}
              rows={3}
              autoFocus
              className="w-full resize-none px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
            />
          </Label>
          <DialogActions>
            <ActionButton
              label="Cancel"
              onClick={() => setSupportDialog(false)}
            />
            <ActionButton
              label="Create support login"
              busy={busy === "support"}
              onClick={async () => {
                const reason = supportReason.trim();
                if (!reason) return;
                setBusy("support");
                setErr(null);
                try {
                  const r = await callTool<{
                    url: string;
                    expires_at?: string;
                  }>("tenant_support_login", { tenant_id: tenant.id, reason });
                  setSupportURL(r);
                  setSupportDialog(false);
                  setSupportReason("");
                  if (r?.url) window.open(r.url, "_blank", "noopener");
                  await onAfterAction();
                } catch (e) {
                  setErr((e as Error).message);
                } finally {
                  setBusy(null);
                }
              }}
            />
          </DialogActions>
        </DialogFrame>
      )}
      {resetDialog && (
        <DialogFrame
          title={`Reset password for ${tenant.slug}`}
          onClose={() => setResetDialog(false)}
        >
          <p className="text-xs text-text-dim">
            This revokes every active session for the admin. The replacement
            password is shown once.
          </p>
          <DialogActions>
            <ActionButton
              label="Cancel"
              onClick={() => setResetDialog(false)}
            />
            <ActionButton
              label="Reset password"
              tone="danger"
              busy={busy === "reset-password"}
              onClick={async () => {
                setBusy("reset-password");
                setErr(null);
                try {
                  const r = await callTool<{
                    slug: string;
                    base_url: string;
                    admin_email: string;
                    admin_password: string;
                  }>("tenant_reset_admin_password", { tenant_id: tenant.id });
                  setResetDialog(false);
                  onResetPassword(r);
                  await onAfterAction();
                } catch (e) {
                  setErr((e as Error).message);
                } finally {
                  setBusy(null);
                }
              }}
            />
          </DialogActions>
        </DialogFrame>
      )}
    </>
  );
}

// ─── Setup-pending banner ───────────────────────────────────────────

function SetupPendingBanner({
  tenantId,
  baseURL,
  setupToken,
  setupURL,
  busy,
  onAttach,
}: {
  tenantId: string;
  baseURL: string;
  setupToken: string | null;
  setupURL: string | null;
  busy: boolean;
  onAttach: (apiKey: string) => Promise<void>;
}) {
  // Reset the api-key field when the operator switches between
  // setup_pending tenants so a half-typed key doesn't leak across.
  const [apiKey, setApiKey] = useState("");
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    setApiKey("");
    setCopied(false);
  }, [tenantId]);

  const url = setupURL || `${baseURL}/?setup=1`;

  return (
    <div className="px-4 py-3 border-b border-border bg-warn/5 space-y-2">
      <div className="flex items-start gap-2">
        <span className="mt-0.5 text-[10px] uppercase tracking-wider font-semibold text-warn">
          Setup pending
        </span>
        <span className="text-xs text-text-dim flex-1">
          Register an admin in the tenant dashboard, generate an API key, then
          paste it below to finish linking.
        </span>
      </div>

      <div className="flex items-center gap-2 text-xs">
        <span className="text-text-dim w-20 flex-shrink-0">Setup URL</span>
        <a
          href={url}
          target="_blank"
          rel="noopener"
          className="font-mono text-accent hover:underline truncate flex-1"
        >
          {url}
        </a>
        <ActionButton
          label="Open ↗"
          onClick={() => window.open(url, "_blank", "noopener")}
        />
      </div>

      <div className="flex items-center gap-2 text-xs">
        <span className="text-text-dim w-20 flex-shrink-0">Setup token</span>
        <code className="font-mono text-text bg-bg-hover px-2 py-0.5 rounded truncate flex-1">
          {setupToken || (
            <span className="text-text-dim italic">
              unavailable — recreate the tenant
            </span>
          )}
        </code>
        {setupToken && (
          <ActionButton
            label={copied ? "Copied" : "Copy"}
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(setupToken);
                setCopied(true);
                window.setTimeout(() => setCopied(false), 1500);
              } catch {
                // Clipboard blocked (insecure context / permission) — fall
                // back to selecting. The token's still visible on-screen.
              }
            }}
          />
        )}
      </div>

      <form
        className="flex items-center gap-2 text-xs"
        onSubmit={async (e) => {
          e.preventDefault();
          if (!apiKey.trim() || busy) return;
          try {
            await onAttach(apiKey.trim());
            setApiKey("");
          } catch {
            // Error surface handled by parent's err state.
          }
        }}
      >
        <span className="text-text-dim w-20 flex-shrink-0">API key</span>
        <input
          type="password"
          value={apiKey}
          onChange={(e) => setApiKey(e.target.value)}
          placeholder="sk-…"
          className="flex-1 px-2 py-1.5 rounded-md border border-border bg-bg-card text-text font-mono"
          disabled={busy}
        />
        <button
          type="submit"
          disabled={busy || !apiKey.trim()}
          className="px-2.5 py-1 rounded-md text-xs font-medium bg-accent/10 text-accent hover:bg-accent/15 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {busy ? "Attaching…" : "Attach key"}
        </button>
      </form>
    </div>
  );
}

