function CredentialRow({
  label,
  value,
  sensitive,
}: {
  label: string;
  value: string;
  sensitive?: boolean;
}) {
  const [revealed, setRevealed] = useState(!sensitive);
  const [copied, setCopied] = useState(false);

  return (
    <div className="mb-2">
      <div className="text-[10px] uppercase tracking-wider text-text-dim font-medium mb-1">
        {label}
      </div>
      <div className="flex items-center gap-2">
        <code className="flex-1 font-mono text-xs px-2 py-1.5 rounded-md bg-bg-hover text-text truncate">
          {revealed ? value : "•".repeat(Math.min(value.length, 32))}
        </code>
        {sensitive && (
          <button
            type="button"
            onClick={() => setRevealed((v) => !v)}
            className="px-2 py-1 rounded-md text-xs text-text-dim hover:text-text hover:bg-bg-hover"
          >
            {revealed ? "Hide" : "Show"}
          </button>
        )}
        <button
          type="button"
          onClick={async () => {
            try {
              await navigator.clipboard.writeText(value);
              setCopied(true);
              window.setTimeout(() => setCopied(false), 1500);
            } catch {
              // Clipboard blocked — value is still on-screen if revealed.
            }
          }}
          className="px-2 py-1 rounded-md text-xs font-medium bg-bg-input hover:bg-bg-hover text-text"
        >
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
    </div>
  );
}

function hostPickerOptions(meta: MetaResp | null, currentID: number) {
  const out = [
    { id: 0, name: "Local server", public_ipv4: "", status: "ready" },
    ...(meta?.instances ?? []),
  ];
  if (currentID > 0 && !out.some((i) => i.id === currentID)) {
    out.push({
      id: currentID,
      name: `Instance ${currentID}`,
      public_ipv4: "",
      status: "ready",
    });
  }
  return out;
}

function CreateTenantDialog({
  onClose,
  onSubmit,
  meta,
  callTool,
}: {
  onClose: () => void;
  onSubmit: (v: {
    slug: string;
    owner_email: string;
    instance_id?: number;
    port?: number;
    template_id?: string;
    project_description?: string;
  }) => Promise<{ ok: boolean; error?: string }>;
  meta: MetaResp | null;
  callTool: ToolCaller;
}) {
  const [slug, setSlug] = useState("");
  const [email, setEmail] = useState("");
  // "Run on": 0 = local parent host; >0 = an Instances row id.
  const [runOn, setRunOn] = useState(0);
  const [port, setPort] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [templateID, setTemplateID] = useState("");
  const [projectDescription, setProjectDescription] = useState("");

  const instances = meta?.instances ?? [];
  const canHost = !!meta?.host_provider_available && instances.length > 0;
  const hosted = runOn > 0;
  const target = instances.find((i) => i.id === runOn);

  return (
    <DialogFrame title="Create tenant" onClose={onClose}>
      <p className="text-xs text-text-dim mb-3">
        Spawns a fresh apteva process with its own data dir and port, registers
        an admin using <code className="font-mono">owner_email</code>, and
        returns a one-shot password + api_key. Slug must be{" "}
        <code className="font-mono">[a-z0-9_-]</code>. May take 15-45s the first
        time (server + core boot).
      </p>
      <Label text="Slug">
        <input
          type="text"
          value={slug}
          onChange={(e) => setSlug(e.target.value)}
          placeholder="acme"
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
          autoFocus
        />
      </Label>
      <Label text="Owner email">
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="ops@acme.com"
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
        />
      </Label>
      <TemplatePicker
        callTool={callTool}
        value={templateID}
        onChange={setTemplateID}
        description={projectDescription}
        onDescriptionChange={setProjectDescription}
        optional
      />
      <Label text="Run on">
        <select
          value={runOn}
          onChange={(e) => setRunOn(Number(e.target.value))}
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
        >
          <option value={0}>Local (this server)</option>
          {instances.map((i) => (
            <option key={i.id} value={i.id}>
              {i.name} — {i.public_ipv4}
              {i.status !== "ready" ? ` (${i.status})` : ""}
            </option>
          ))}
        </select>
      </Label>
      {!canHost && (
        <p className="text-xs text-text-dim -mt-1">
          {meta?.host_provider_available
            ? "No ready remote instances. Provision one in the Instances app to host elsewhere."
            : "Install + bind the Instances app to host tenants on remote VPSes."}
        </p>
      )}
      {hosted && (
        <Label text="Port (optional)">
          <input
            type="number"
            value={port}
            onChange={(e) => setPort(e.target.value)}
            placeholder="auto (7100 + tenants on this instance)"
            className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text font-mono"
          />
        </Label>
      )}
      {hosted && target && (
        <div className="text-xs text-text-dim font-mono">
          Will spawn on <span className="text-text">{target.name}</span> (
          {target.public_ipv4})
        </div>
      )}
      {err && <p className="text-xs text-error mt-2">{err}</p>}
      <DialogActions>
        <ActionButton label="Cancel" onClick={onClose} />
        <ActionButton
          label={busy ? "Spawning…" : "Spawn"}
          busy={busy}
          onClick={async () => {
            if (!slug || !email) {
              setErr("slug and owner_email are required");
              return;
            }
            setBusy(true);
            setErr(null);
            const r = await onSubmit({
              slug,
              owner_email: email,
              ...(hosted ? { instance_id: runOn } : {}),
              ...(hosted && port.trim() ? { port: Number(port) } : {}),
              ...(templateID ? { template_id: templateID } : {}),
              ...(templateID && projectDescription.trim()
                ? { project_description: projectDescription.trim() }
                : {}),
            });
            setBusy(false);
            if (!r.ok) setErr(r.error || "failed");
          }}
        />
      </DialogActions>
    </DialogFrame>
  );
}

function TemplatePicker({
  callTool,
  value,
  onChange,
  description,
  onDescriptionChange,
  optional = false,
}: {
  callTool: ToolCaller;
  value: string;
  onChange: (value: string) => void;
  description: string;
  onDescriptionChange: (value: string) => void;
  optional?: boolean;
}) {
  const [templates, setTemplates] = useState<ProjectTemplateSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    callTool<ProjectTemplateListResp>("tenant_template_list", {
      include_system: true,
    })
      .then((result) => {
        if (cancelled) return;
        setTemplates(result.templates ?? []);
        setError(null);
      })
      .catch((e) => {
        if (cancelled) return;
        setError((e as Error).message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [callTool]);

  return (
    <>
      <Label
        text={optional ? "Project template (optional)" : "Project template"}
      >
        <select
          value={value}
          disabled={loading || !!error}
          onChange={(e) => {
            const next = e.target.value;
            onChange(next);
            const selected = templates.find((template) => template.id === next);
            onDescriptionChange(selected?.description || selected?.name || "");
          }}
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text disabled:opacity-60"
        >
          <option value="">
            {loading
              ? "Loading templates…"
              : optional
                ? "No template"
                : "Select a template"}
          </option>
          {templates.map((template) => (
            <option key={template.id} value={template.id}>
              {template.name} · {template.source}
              {template.revision ? ` r${template.revision}` : ""}
            </option>
          ))}
        </select>
      </Label>
      {error && (
        <p className="text-xs text-error -mt-1">
          Template catalog unavailable: {error}. Refresh Fleet's approved
          permissions after upgrading.
        </p>
      )}
      {value && (
        <Label text="Project description">
          <textarea
            value={description}
            onChange={(e) => onDescriptionChange(e.target.value)}
            rows={3}
            placeholder="Context inserted into the template's agent directives"
            className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text resize-y"
          />
        </Label>
      )}
    </>
  );
}

function ApplyTemplateDialog({
  tenant,
  callTool,
  onClose,
  onSubmit,
}: {
  tenant: Tenant;
  callTool: ToolCaller;
  onClose: () => void;
  onSubmit: (args: {
    template_id: string;
    project_description?: string;
    target_project_id?: string;
  }) => Promise<{ ok: boolean; error?: string }>;
}) {
  const [targetProject, setTargetProject] = useState("");
  const [projects, setProjects] = useState<{ id: string; name: string }[]>([]);
  useEffect(() => {
    let active = true;
    callTool<{ result: { id: string; name: string }[] }>(
      "tenant_platform_call",
      { tenant_id: tenant.id, resource: "projects", action: "list" },
    )
      .then((r) => {
        if (!active) return;
        setProjects(r.result);
        const choice =
          r.result.length === 1
            ? r.result[0]
            : r.result.find((p) => p.name.toLowerCase() === "default");
        if (choice) setTargetProject(choice.id);
      })
      .catch((e) => {
        if (active) setErr(String(e));
      });
    return () => {
      active = false;
    };
  }, [tenant.id, callTool]);

  const [templateID, setTemplateID] = useState("");
  const [projectDescription, setProjectDescription] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  return (
    <DialogFrame title={`Apply template to ${tenant.slug}`} onClose={onClose}>
      <p className="text-xs text-text-dim mb-3">
        Copies an exact snapshot from this parent project, then lets the tenant
        install required apps, create missing agents, and merge dashboard
        widgets. Existing agents with the same names are preserved.
      </p>
      <Label text="Target project">
        <select
          aria-label="Target project"
          value={targetProject}
          onChange={(e) => setTargetProject(e.target.value)}
          className="w-full border border-border rounded p-2"
        >
          <option value="">Select a project</option>
          {projects.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>
      </Label>
      <TemplatePicker
        callTool={callTool}
        value={templateID}
        onChange={setTemplateID}
        description={projectDescription}
        onDescriptionChange={setProjectDescription}
      />
      {err && <p className="text-xs text-error mt-2">{err}</p>}
      <DialogActions>
        <ActionButton label="Cancel" onClick={onClose} />
        <ActionButton
          label={busy ? "Applying…" : "Apply"}
          busy={busy}
          onClick={async () => {
            if (!templateID || !targetProject) {
              setErr("Select a project template and target project");
              return;
            }
            setBusy(true);
            setErr(null);
            const result = await onSubmit({
              template_id: templateID,
              ...(targetProject.trim()
                ? { target_project_id: targetProject.trim() }
                : {}),
              ...(projectDescription.trim()
                ? { project_description: projectDescription.trim() }
                : {}),
            });
            setBusy(false);
            if (!result.ok) setErr(result.error || "failed");
          }}
        />
      </DialogActions>
    </DialogFrame>
  );
}

function CloneTenantDialog({
  tenant,
  meta,
  onClose,
  onSubmit,
}: {
  tenant: Tenant;
  meta: MetaResp | null;
  onClose: () => void;
  onSubmit: (v: {
    slug: string;
    owner_email?: string;
    instance_id: number;
    port?: number;
    start: boolean;
  }) => Promise<{ ok: boolean; error?: string }>;
}) {
  const [slug, setSlug] = useState(`${tenant.slug}-copy`);
  const [email, setEmail] = useState(tenant.owner_email);
  const hostOptions = useMemo(
    () => hostPickerOptions(meta, tenant.instance_id ?? 0),
    [meta, tenant.instance_id],
  );
  const [instanceID, setInstanceID] = useState(tenant.instance_id ?? 0);
  const [port, setPort] = useState("");
  const [start, setStart] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const target = hostOptions.find((i) => i.id === instanceID);

  return (
    <DialogFrame title={`Clone ${tenant.slug}`} onClose={onClose}>
      <p className="text-xs text-text-dim mb-3">
        Creates a new tenant from the current data dir. The source tenant is not
        stopped, restarted, or changed. Domains are not copied to the clone.
      </p>
      <Label text="New slug">
        <input
          type="text"
          value={slug}
          onChange={(e) => setSlug(e.target.value)}
          placeholder="acme-copy"
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
          autoFocus
        />
      </Label>
      <Label text="Owner email">
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder={tenant.owner_email}
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
        />
      </Label>
      <Label text="Target host">
        <select
          value={instanceID}
          onChange={(e) => setInstanceID(Number(e.target.value))}
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
        >
          {hostOptions.map((i) => (
            <option key={i.id} value={i.id}>
              {i.id === 0 ? "Local server" : `${i.name} — ${i.public_ipv4}`}
              {i.status !== "ready" ? ` (${i.status})` : ""}
            </option>
          ))}
        </select>
      </Label>
      <Label text="Port (optional)">
        <input
          type="number"
          value={port}
          onChange={(e) => setPort(e.target.value)}
          placeholder="auto"
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text font-mono"
        />
      </Label>
      <label className="flex items-center gap-2 text-xs text-text">
        <input
          type="checkbox"
          checked={start}
          onChange={(e) => setStart(e.target.checked)}
          className="h-3.5 w-3.5"
        />
        Run the clone quarantine rehearsal after copy (the clone remains
        stopped)
      </label>
      {tenant.domain && (
        <div className="text-xs text-text-dim font-mono">
          Domain stays on source: {tenant.domain}
        </div>
      )}
      {target && (
        <div className="text-xs text-text-dim font-mono">
          Clone target:{" "}
          {target.id === 0
            ? "local server"
            : `${target.name} (${target.public_ipv4})`}
        </div>
      )}
      {err && <p className="text-xs text-error mt-2">{err}</p>}
      <DialogActions>
        <ActionButton label="Cancel" onClick={onClose} />
        <ActionButton
          label={busy ? "Cloning…" : "Clone"}
          busy={busy}
          onClick={async () => {
            if (!slug.trim()) {
              setErr("slug is required");
              return;
            }
            setBusy(true);
            setErr(null);
            const r = await onSubmit({
              slug: slug.trim(),
              ...(email.trim() && email.trim() !== tenant.owner_email
                ? { owner_email: email.trim() }
                : {}),
              instance_id: instanceID,
              ...(port.trim() ? { port: Number(port) } : {}),
              start,
            });
            setBusy(false);
            if (!r.ok) setErr(r.error || "failed");
          }}
        />
      </DialogActions>
    </DialogFrame>
  );
}

// ─── Move-tenant dialog ─────────────────────────────────────────────
//
// Migrates a Fleet-managed tenant between local and Instances hosts.
// Cold move — the tenant is briefly down while fleet stops it,
// transfers the data dir, starts the target, and re-points ingress.

function MoveTenantDialog({
  tenant,
  meta,
  onClose,
  onSubmit,
}: {
  tenant: Tenant;
  meta: MetaResp;
  onClose: () => void;
  onSubmit: (args: {
    instance_id: number;
    port?: number;
    retain_source: boolean;
  }) => Promise<{ ok: boolean; error?: string }>;
}) {
  const currentID = tenant.instance_id ?? 0;
  const hostOptions = hostPickerOptions(meta, currentID);
  const defaultTarget =
    hostOptions.find((i) => i.id !== currentID)?.id ?? currentID;
  const [instanceID, setInstanceID] = useState(defaultTarget);
  const [port, setPort] = useState("");
  const [retainSource, setRetainSource] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const target = hostOptions.find((i) => i.id === instanceID);
  const sameHost = instanceID === currentID;

  return (
    <DialogFrame title={`Move ${tenant.slug}`} onClose={onClose}>
      <p className="text-xs text-text-dim mb-3">
        Relocates this tenant to another host. Fleet stops the source, transfers
        its data dir, starts the target, and re-points ingress. The tenant is
        briefly <span className="text-text">down</span>. If anything fails
        before commit, the source is restarted.
      </p>
      <Label text="Target host">
        <select
          value={instanceID}
          onChange={(e) => setInstanceID(Number(e.target.value))}
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text"
        >
          {hostOptions.map((i) => (
            <option key={i.id} value={i.id}>
              {i.id === 0 ? "Local server" : `${i.name} — ${i.public_ipv4}`}
              {i.status !== "ready" ? ` (${i.status})` : ""}
            </option>
          ))}
        </select>
      </Label>
      <Label text="Port (optional)">
        <input
          type="number"
          value={port}
          onChange={(e) => setPort(e.target.value)}
          placeholder={
            instanceID === 0 ? "auto" : "auto (7100 + tenants on this instance)"
          }
          className="w-full px-2 py-1.5 text-sm rounded-md border border-border bg-bg-card text-text font-mono"
        />
      </Label>
      {!sameHost && (
        <label className="flex items-center gap-2 text-xs text-text">
          <input
            type="checkbox"
            checked={retainSource}
            onChange={(e) => setRetainSource(e.target.checked)}
            className="h-3.5 w-3.5"
          />
          Retain stopped source until explicit finalization
        </label>
      )}
      {target && (
        <div className="text-xs text-text-dim font-mono">
          {tenant.base_url} →{" "}
          {target.id === 0
            ? "local server"
            : `${target.name} (${target.public_ipv4})`}
        </div>
      )}
      {sameHost && !port.trim() && (
        <p className="text-xs text-warn mt-2">
          Pick a different host or specify a new port.
        </p>
      )}
      {err && <p className="text-xs text-error mt-2">{err}</p>}
      <DialogActions>
        <ActionButton label="Cancel" onClick={onClose} />
        <ActionButton
          label={busy ? "Moving…" : "Move"}
          busy={busy}
          onClick={async () => {
            if (sameHost && !port.trim()) {
              setErr("pick a different host or specify a new port");
              return;
            }
            setBusy(true);
            setErr(null);
            const r = await onSubmit({
              instance_id: instanceID,
              ...(port.trim() ? { port: Number(port) } : {}),
              retain_source: !sameHost && retainSource,
            });
            setBusy(false);
            if (!r.ok) setErr(r.error || "failed");
          }}
        />
      </DialogActions>
    </DialogFrame>
  );
}

