function DialogFrame({
  title,
  children,
  onClose,
}: {
  title: string;
  children: React.ReactNode;
  onClose: () => void;
}) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
      <div
        role="dialog"
        aria-modal="true"
        aria-label={title}
        className="w-[min(100%,26rem)] max-h-[calc(100vh-2rem)] overflow-y-auto rounded-md border border-border bg-bg-card shadow-xl"
      >
        <div className="flex items-center justify-between px-4 py-2.5 border-b border-border">
          <h2 className="text-sm font-semibold text-text">{title}</h2>
          <button
            type="button"
            onClick={onClose}
            className="text-text-dim hover:text-text text-lg leading-none"
            aria-label="Close"
          >
            ×
          </button>
        </div>
        <div className="p-4 space-y-3">{children}</div>
      </div>
    </div>
  );
}

function DialogActions({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-center justify-end gap-2 pt-2">{children}</div>
  );
}

function Label({
  text,
  children,
}: {
  text: string;
  children: React.ReactNode;
}) {
  return (
    <label className="block">
      <span className="block text-[10px] uppercase tracking-wider text-text-dim font-medium mb-1">
        {text}
      </span>
      {children}
    </label>
  );
}

// ─── Domain block ───────────────────────────────────────────────────

function DomainBlock({
  tenant,
  meta,
  busy,
  onAttach,
  onDetach,
}: {
  tenant: Tenant;
  meta: MetaResp | null;
  busy: boolean;
  onAttach: () => void;
  onDetach: () => void;
}) {
  // Metadata not loaded yet → render a quiet hint so the pane doesn't
  // go silent while the attach affordance initializes.
  if (!tenant.domain && !meta) {
    return (
      <div className="px-4 py-2 border-b border-border text-[11px] text-text-dim">
        <span className="font-medium">Public hostname</span> · Loading hostname
        controls…
      </div>
    );
  }
  if (!tenant.domain) {
    return (
      <div className="flex items-center gap-2 px-4 py-2 border-b border-border bg-accent/5">
        <span className="text-[11px] uppercase tracking-wider text-text-dim font-semibold">
          Domain
        </span>
        <span className="text-xs text-text-dim flex-1">Not attached</span>
        <ActionButton label="Attach domain" onClick={onAttach} />
      </div>
    );
  }
  const clientManagedDNS = !tenant.domain_record_id;
  const directIngress = tenant.ingress_mode === "direct";
  const transitioningIngress = tenant.ingress_mode === "direct_pending";
  const cert =
    clientManagedDNS || directIngress || transitioningIngress
      ? undefined
      : meta?.certs?.[tenant.domain];
  const certVariant: PillVariant = !cert
    ? "neutral"
    : cert.status === "live"
      ? "success"
      : cert.status === "pending" || cert.status === "issuing"
        ? "info"
        : cert.status === "error" || cert.status === "failed"
          ? "error"
          : "warn";
  return (
    <div className="flex items-center gap-2 px-4 py-2 border-b border-border bg-accent/5 flex-wrap">
      <span className="text-[11px] uppercase tracking-wider text-text-dim font-semibold">
        Domain
      </span>
      <a
        href={`https://${tenant.domain}`}
        target="_blank"
        rel="noopener"
        className="font-mono text-xs text-accent hover:underline"
      >
        {tenant.domain}
      </a>
      {cert && (
        <span title={cert.error || cert.expires_at || ""}>
          <StatusPill
            variant={certVariant}
          >{`cert · ${cert.status}`}</StatusPill>
        </span>
      )}
      {clientManagedDNS && (
        <StatusPill
          variant={
            directIngress
              ? "success"
              : transitioningIngress
                ? "warn"
                : "success"
          }
        >
          {directIngress
            ? "instance HTTPS"
            : transitioningIngress
              ? "transitioning"
              : "server ingress"}
        </StatusPill>
      )}
      {!cert && tenant.domain && !clientManagedDNS && (
        <StatusPill
          variant={
            directIngress ? "success" : transitioningIngress ? "warn" : "info"
          }
        >
          {directIngress
            ? "instance HTTPS"
            : transitioningIngress
              ? "transitioning"
              : "server ingress"}
        </StatusPill>
      )}
      <span className="flex-1" />
      <ActionButton
        label={busy ? "Detaching…" : "Detach"}
        busy={busy}
        tone="danger"
        onClick={onDetach}
      />
    </div>
  );
}

function HostedIngressBlock({
  tenant,
  instance,
  busy,
  onPrepare,
  onVerify,
  onFinalize,
  onRestore,
  onDisable,
}: {
  tenant: Tenant;
  instance?: InstanceOption;
  busy: string | null;
  onPrepare: () => void;
  onVerify: () => void;
  onFinalize: () => void;
  onRestore: () => void;
  onDisable: () => void;
}) {
  const mode = tenant.ingress_mode || "parent";
  const variant: PillVariant =
    mode === "direct"
      ? "success"
      : mode === "direct_pending"
        ? "warn"
        : "neutral";
  const label =
    mode === "direct"
      ? "direct"
      : mode === "direct_pending"
        ? "transitioning"
        : "via parent";
  return (
    <div className="flex flex-wrap items-center gap-2 px-4 py-2 border-b border-border">
      <span className="text-[11px] uppercase tracking-wider text-text-dim font-semibold">
        Hosted ingress
      </span>
      <StatusPill variant={variant}>{label}</StatusPill>
      {instance?.public_ipv4 && (
        <span className="font-mono text-xs text-text-dim">
          {instance.public_ipv4}
        </span>
      )}
      {tenant.ingress_error && (
        <span
          className="basis-full text-xs text-error"
          title={tenant.ingress_error}
        >
          {tenant.ingress_error}
        </span>
      )}
      <span className="flex-1" />
      {mode === "parent" && (
        <ActionButton
          label="Use instance ingress"
          busy={busy === "ingress-prepare"}
          onClick={onPrepare}
        />
      )}
      {mode === "direct_pending" && (
        <>
          <ActionButton
            label="Verify"
            busy={busy === "ingress-verify"}
            onClick={onVerify}
          />
          <ActionButton
            label="Finalize"
            busy={busy === "ingress-finalize"}
            onClick={onFinalize}
          />
          <ActionButton
            label="Restore parent"
            busy={busy === "ingress-restore"}
            onClick={onRestore}
          />
          <ActionButton
            label="Disable direct"
            busy={busy === "ingress-disable"}
            tone="danger"
            onClick={onDisable}
          />
        </>
      )}
      {mode === "direct" && (
        <ActionButton
          label="Restore parent"
          busy={busy === "ingress-restore"}
          onClick={onRestore}
        />
      )}
    </div>
  );
}

