// ─── Helpers ────────────────────────────────────────────────────────

function shortBaseURL(url: string): string {
  // Strip protocol for compactness, keep host:port intact.
  return url.replace(/^https?:\/\//, "");
}

function formatTime(iso?: string): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  const now = Date.now();
  const diff = (now - d.getTime()) / 1000;
  if (diff < 60) return `${Math.floor(diff)}s ago`;
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  return d.toLocaleString();
}

function StorageDialog({
  callTool,
  onClose,
}: {
  callTool: ToolCaller;
  onClose: () => void;
}) {
  const [data, setData] = useState<{
    free_bytes: number;
    candidates: { path: string; kind: string }[];
  } | null>(null);
  const [selected, setSelected] = useState<string[]>([]);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let active = true;
    callTool<{
      free_bytes: number;
      candidates: { path: string; kind: string }[];
    }>("fleet_storage_list", {})
      .then((r) => {
        if (active) setData(r);
      })
      .catch((e) => {
        if (active) setError(String(e));
      });
    return () => {
      active = false;
    };
  }, [callTool]);
  return (
    <DialogFrame title="Local storage and cleanup" onClose={onClose}>
      <p>
        {data
          ? `${(data.free_bytes / 2 ** 30).toFixed(1)} GiB available`
          : "Loading storage…"}
      </p>
      <p className="text-xs text-text-dim">
        Unused runtime versions and restore copies become eligible after 30
        days. Select only copies you no longer need. Active runtimes and pending
        operations are protected.
      </p>
      {data?.candidates.map((item) => (
        <label key={item.path} className="block my-2 text-xs">
          <input
            type="checkbox"
            checked={selected.includes(item.path)}
            onChange={(e) =>
              setSelected(
                e.target.checked
                  ? [...selected, item.path]
                  : selected.filter((p) => p !== item.path),
              )
            }
          />
          {item.kind}: {item.path}
        </label>
      ))}
      {data?.candidates.length === 0 && <p>No eligible files to remove.</p>}
      {error && <p role="alert">{error}</p>}
      <DialogActions>
        <ActionButton label="Close" onClick={onClose} />
        <ActionButton
          label="Delete selected copies"
          busy={busy}
          disabled={!selected.length || busy}
          onClick={async () => {
            setBusy(true);
            try {
              await callTool("fleet_storage_cleanup", {
                paths: selected,
                confirm: true,
              });
              setData((prev) =>
                prev
                  ? {
                      ...prev,
                      candidates: prev.candidates.filter(
                        (c) => !selected.includes(c.path),
                      ),
                    }
                  : prev,
              );
              setSelected([]);
            } catch (e) {
              setError(String(e));
            } finally {
              setBusy(false);
            }
          }}
        />
      </DialogActions>
    </DialogFrame>
  );
}
